	}
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	var s3, s4 string
	if scanner.Scan() {
		s3 = scanner.Text()
	}
	if scanner.Scan() {
		s4 = scanner.Text()
	}

	s3 = strings.ToUpper(s3)
	s4 = strings.ToUpper(s4)

	for i := 0; i < len(s3); i++ {
		if i >= len(s4) {
			fmt.Println(1)
			return
		}

		if s3[i] == s4[i] {
			if i == len(s3)-1 && len(s3) == len(s4) {
				fmt.Println(0)
			}
			continue
		}

		if s3[i] > s4[i] {
			fmt.Println(1)
		} else {
			fmt.Println(-1)
		}
		return
	}

	if len(s3) == len(s4) {
		fmt.Println(0)
	} else if len(s3) < len(s4) {
		fmt.Println(-1)
	} else {
		fmt.Println(1)
	}
}

